import React from "react";

import type { AboutTemplate } from "../../templates/about/default-template";
import useInView from "../shared/useInView";
import type { AboutApproachContent, AboutContent } from "./types";

export type AboutProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: AboutTemplate;
  content: AboutContent;
  enabled?: boolean;
};

/**
 * The About story split.
 *
 * Presentational and nothing else: it receives its words, its photograph and
 * its stylesheet, and it decides none of them. The heading is an `h1` because
 * this is the page's own subject — About is a page in its own right, not a
 * section bolted onto another one.
 */
export default function About({ template, content, enabled = true }: AboutProps) {
  const { ref, inView } = useInView<HTMLElement>();

  if (!enabled) return null;

  const root = template.rootClass;

  return (
    <section
      ref={ref}
      className={`${root}${inView ? ` ${root}--in` : ""}`}
      aria-labelledby="kr-about-title"
    >
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__inner`}>
        <div className={`${root}__content`}>
          {/* The gold rule before it is decoration and is drawn in CSS, so
              there is no empty span here for a screen reader to trip over. */}
          <p className={`${root}__eyebrow`}>{content.eyebrow}</p>

          <h1 className={`${root}__title`} id="kr-about-title">
            {content.title}
          </h1>

          <div className={`${root}__body`}>
            {content.paragraphs.map((paragraph) => (
              <p key={paragraph.slice(0, 40)}>{paragraph}</p>
            ))}
          </div>
        </div>

        <div className={`${root}__visual`}>
          {/* Three photographs, one composition. The tall one anchors it and
              the two beside it stack — which is why the lead is a portrait
              crop and the others are close to square. */}
          <div className={`${root}__collage`}>
            <figure className={`${root}__frame ${root}__frame--lead`}>
              <img
                className={`${root}__image`}
                src={content.collage.lead.src}
                srcSet={content.collage.lead.srcSet}
                /* Mirrors the 980px stack: full width below it, and about a
                   third of the viewport above it once the collage is split. */
                sizes={content.collage.lead.srcSet ? "(max-width: 980px) 58vw, 30vw" : undefined}
                alt={content.collage.lead.alt}
                loading="eager"
                decoding="async"
              />
            </figure>

            <figure className={`${root}__frame ${root}__frame--upper`}>
              <img
                className={`${root}__image`}
                src={content.collage.upper.src}
                srcSet={content.collage.upper.srcSet}
                sizes={content.collage.upper.srcSet ? "(max-width: 980px) 40vw, 22vw" : undefined}
                alt={content.collage.upper.alt}
                loading="lazy"
                decoding="async"
              />
            </figure>

            <figure className={`${root}__frame ${root}__frame--lower`}>
              <img
                className={`${root}__image`}
                src={content.collage.lower.src}
                srcSet={content.collage.lower.srcSet}
                sizes={content.collage.lower.srcSet ? "(max-width: 980px) 40vw, 22vw" : undefined}
                alt={content.collage.lower.alt}
                loading="lazy"
                decoding="async"
              />
            </figure>
          </div>

          <ul className={`${root}__cards`}>
            {content.cards.map((card, index) => {
              const Icon = card.icon;

              return (
                <li
                  key={card.title}
                  className={`${root}__card`}
                  style={{
                    ["--kr-about-delay" as string]: `${
                      template.timing.cardDelay + index * template.timing.cardStagger
                    }ms`,
                  }}
                >
                  <span className={`${root}__card-icon`} aria-hidden="true">
                    <Icon size={16} strokeWidth={1.5} />
                  </span>
                  <h2 className={`${root}__card-title`}>{card.title}</h2>
                  <p className={`${root}__card-text`}>{card.text}</p>
                </li>
              );
            })}
          </ul>
        </div>
      </div>
    </section>
  );
}

export type AboutApproachProps = {
  template: AboutTemplate;
  content: AboutApproachContent;
  /** The shared section heading, composed by the primitive. */
  heading?: React.ReactNode;
  enabled?: boolean;
};

/**
 * The three principles below the story.
 *
 * One restrained follow-up section, deliberately. An About page that keeps
 * going becomes a corporate manifesto, and nobody reads the eighth panel.
 */
export function AboutApproach({
  template,
  content,
  heading,
  enabled = true,
}: AboutApproachProps) {
  const { ref, inView } = useInView<HTMLElement>();

  if (!enabled) return null;

  const root = template.approachClass;

  return (
    <section ref={ref} className={`${root}${inView ? ` ${root}--in` : ""}`}>
      <div className={`${root}__inner`}>
        {heading}

        <ol className={`${root}__list`}>
          {content.principles.map((principle, index) => (
            <li
              key={principle.number}
              className={`${root}__step`}
              style={{
                ["--kr-about-delay" as string]: `${index * template.timing.stepStagger}ms`,
              }}
            >
              {/* Decorative numbering: the list is already ordered, so reading
                  "01" aloud before every heading adds nothing. */}
              <span className={`${root}__number`} aria-hidden="true">
                {principle.number}
              </span>
              <h3 className={`${root}__title`}>{principle.title}</h3>
              <p className={`${root}__text`}>{principle.text}</p>
            </li>
          ))}
        </ol>
      </div>
    </section>
  );
}
