// Styling for the About page.
//
// Two sections, one sheet: the story split at the top and the three principles
// beneath it. They share a stylesheet because they are one page and one idea,
// and splitting them would mean two files to keep in step for no gain.
//
// Notes on the composition:
//
// 1. The two columns are 47/53 — the visual carries slightly more, the same
//    ratio Why Choose Us uses. Kelley Road pages should look like they were
//    laid out by the same hand, and a 50/50 split reads as a slide, not a page.
//
// 2. The four cards sit UNDER the image, in the visual column, so the right
//    side is one composition rather than two things stacked by accident. On a
//    phone the image leads and the cards follow, which is the order somebody
//    actually reads them in.
//
// 3. Nothing is rounded beyond 3px and nothing carries a shadow. The reference
//    Nate sent uses large radii and soft cards; that is its brand. Ours is thin
//    borders and square-ish corners, and the page has to belong here.

import template1 from "./template-1";

export type AboutTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  approachClass: string;
  timing: typeof template1.timing;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
/* ── the story split ──────────────────────────────────── */
.kr-about {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
  overflow: hidden;
}
.kr-about__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  display: grid;
  grid-template-columns: ${layout.contentColumn} ${layout.visualColumn};
  align-items: start;
  gap: ${spacing.columnGap}px;
}

.kr-about__content { min-width: 0; }

.kr-about__eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 ${spacing.eyebrowGap}px;
  color: ${color.eyebrow};
  font-family: ${typography.eyebrowFamily};
  font-size: ${typography.eyebrowSize}px;
  font-weight: ${typography.eyebrowWeight};
  letter-spacing: ${typography.eyebrowTracking};
  text-transform: uppercase;

  opacity: 0;
  transform: translateY(10px);
  transition: opacity ${timing.eyebrow}ms ${ease}, transform ${timing.eyebrow}ms ${ease};
}
/* The site's usual accent gesture: a short gold rule, not a coloured pill. */
.kr-about__eyebrow::before {
  content: "";
  width: ${layout.ruleWidth}px;
  height: ${layout.ruleHeight}px;
  flex-shrink: 0;
  background: ${color.rule};
}

.kr-about__title {
  margin: 0 0 ${spacing.titleGap}px;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: ${typography.titleLeading};

  opacity: 0;
  transform: translateY(14px);
  transition: opacity ${timing.title}ms ${ease} ${timing.titleDelay}ms,
    transform ${timing.title}ms ${ease} ${timing.titleDelay}ms;
}

.kr-about__body {
  opacity: 0;
  transform: translateY(12px);
  transition: opacity ${timing.body}ms ${ease} ${timing.bodyDelay}ms,
    transform ${timing.body}ms ${ease} ${timing.bodyDelay}ms;
}
.kr-about__body p {
  margin: 0 0 ${spacing.paragraphGap}px;
  color: ${color.body};
  font-family: ${typography.bodyFamily};
  font-size: ${typography.bodySize};
  font-weight: ${typography.bodyWeight};
  line-height: ${typography.bodyLeading};
}
.kr-about__body p:last-child { margin-bottom: 0; }

/* ── the visual column ────────────────────────────────── */
.kr-about__visual { min-width: 0; }

/* Three photographs in one block: a tall lead, and two stacked beside it.
   One picture of a building says nothing about a property manager; these three
   say who runs it, what the homes are like, and where they sit. */
.kr-about__collage {
  display: grid;
  grid-template-columns: ${layout.collageLeadColumn} ${layout.collageSideColumn};
  grid-template-rows: 1fr 1fr;
  gap: ${layout.collageGap}px;
  aspect-ratio: ${layout.collageAspect};
  margin: 0 0 ${spacing.mediaGap}px;
}

.kr-about__frame {
  position: relative;
  margin: 0;
  min-width: 0;
  min-height: 0;
  border-radius: ${layout.radius}px;
  overflow: hidden;
  background: ${color.mediaPlaceholder};

  opacity: 0;
  /* A clip wipe rather than a fade, matching Why Choose Us. clip-path runs on
     the compositor, so it stays smooth on modest hardware. */
  clip-path: inset(0 0 14% 0);
  transition: opacity ${timing.media}ms ${ease} var(--kr-about-frame-delay, 0ms),
    clip-path ${timing.media}ms ${ease} var(--kr-about-frame-delay, 0ms);
}
/* The lead spans both rows. The two beside it arrive just after it, so the
   block assembles rather than appearing all at once. */
.kr-about__frame--lead {
  grid-row: 1 / span 2;
  --kr-about-frame-delay: ${timing.mediaDelay}ms;
}
.kr-about__frame--upper { --kr-about-frame-delay: ${timing.mediaDelay + 120}ms; }
.kr-about__frame--lower { --kr-about-frame-delay: ${timing.mediaDelay + 240}ms; }

.kr-about__image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
/* The portrait is framed for a face; centring it crops the head on a narrow
   column. */
.kr-about__frame--lead .kr-about__image { object-position: 50% 22%; }

.kr-about__cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: ${spacing.cardGap}px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-about__card {
  padding: ${spacing.cardPadding}px;
  background: ${color.cardBackground};
  border: 1px solid ${color.cardBorder};
  border-radius: ${layout.cardRadius}px;

  opacity: 0;
  transform: translateY(12px);
  transition: opacity ${timing.card}ms ${ease} var(--kr-about-delay, 0ms),
    transform ${timing.card}ms ${ease} var(--kr-about-delay, 0ms),
    border-color ${timing.hover}ms ${ease};
}
.kr-about__card:hover { border-color: ${color.cardIcon}; }

.kr-about__card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: ${layout.cardIconSize}px;
  height: ${layout.cardIconSize}px;
  margin-bottom: ${spacing.cardIconGap}px;
  border-radius: 50%;
  background: ${color.cardIconBackground};
  color: ${color.cardIcon};
}

.kr-about__card-title {
  margin: 0 0 ${spacing.cardTitleGap}px;
  color: ${color.cardTitle};
  font-family: ${typography.cardTitleFamily};
  font-size: ${typography.cardTitleSize};
  font-weight: ${typography.cardTitleWeight};
  letter-spacing: ${typography.cardTitleTracking};
}
.kr-about__card-text {
  margin: 0;
  color: ${color.cardText};
  font-family: ${typography.cardTextFamily};
  font-size: ${typography.cardTextSize}px;
  font-weight: ${typography.cardTextWeight};
  line-height: ${typography.cardTextLeading};
}

/* ── revealed ─────────────────────────────────────────── */
.kr-about--in .kr-about__eyebrow,
.kr-about--in .kr-about__title,
.kr-about--in .kr-about__body,
.kr-about--in .kr-about__card { opacity: 1; transform: none; }
.kr-about--in .kr-about__frame { opacity: 1; clip-path: inset(0 0 0 0); }

/* ── our approach ─────────────────────────────────────── */
.kr-approach {
  background: ${color.approachBackground};
  padding: ${spacing.approachTop}px 0 ${spacing.approachBottom}px;
}
.kr-approach__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}
.kr-approach__list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: ${spacing.approachGap}px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-approach__step {
  padding-top: 22px;
  border-top: 1px solid ${color.stepDivider};

  opacity: 0;
  transform: translateY(12px);
  transition: opacity ${timing.step}ms ${ease} var(--kr-about-delay, 0ms),
    transform ${timing.step}ms ${ease} var(--kr-about-delay, 0ms);
}
.kr-approach--in .kr-approach__step { opacity: 1; transform: none; }

.kr-approach__number {
  display: block;
  margin-bottom: ${spacing.stepNumberGap}px;
  color: ${color.stepNumber};
  font-family: ${typography.stepNumberFamily};
  font-size: ${typography.stepNumberSize}px;
  font-weight: ${typography.stepNumberWeight};
  letter-spacing: ${typography.stepNumberTracking};
}
.kr-approach__title {
  margin: 0 0 ${spacing.stepTitleGap}px;
  color: ${color.stepTitle};
  font-family: ${typography.stepTitleFamily};
  font-size: ${typography.stepTitleSize};
  font-weight: ${typography.stepTitleWeight};
  letter-spacing: ${typography.stepTitleTracking};
}
.kr-approach__text {
  margin: 0;
  color: ${color.stepText};
  font-family: ${typography.stepTextFamily};
  font-size: ${typography.stepTextSize}px;
  font-weight: ${typography.stepTextWeight};
  line-height: ${typography.stepTextLeading};
}

/* ── narrow screens ───────────────────────────────────── */
@media (max-width: ${layout.stackBelow}px) {
  .kr-about {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-about__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.columnGapCompact}px;
    padding: 0 ${spacing.gutterCompact}px;
  }
  /* The photograph leads on a phone, then the story, then the cards — which is
     the order somebody actually takes the page in. */
  .kr-about__visual { display: contents; }
  .kr-about__collage { order: -1; margin-bottom: 0; }
  .kr-about__content { order: 0; }
  .kr-about__cards { order: 1; }
}

@media (max-width: ${layout.approachStackBelow}px) {
  .kr-approach {
    padding: ${spacing.approachTopCompact}px 0 ${spacing.approachBottomCompact}px;
  }
  .kr-approach__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-approach__list {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.approachRowGap}px;
  }
}

/* Below this the collage rearranges rather than shrinking in place: the lead
   takes the full width and the other two sit beneath it. Keeping the desktop
   three-up down to 320px would render the pair as thumbnails barely 110px
   wide, which is worse than showing fewer, bigger photographs. */
@media (max-width: ${layout.collageRelayoutBelow}px) {
  .kr-about__collage {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: auto auto;
    aspect-ratio: auto;
  }
  .kr-about__frame--lead {
    grid-column: 1 / -1;
    grid-row: auto;
    aspect-ratio: 16 / 10;
  }
  .kr-about__frame--upper,
  .kr-about__frame--lower { aspect-ratio: 1 / 1; }
  /* Wide crop now, so the face sits nearer the middle of the frame. */
  .kr-about__frame--lead .kr-about__image { object-position: 50% 30%; }
}

@media (max-width: ${layout.cardsSingleBelow}px) {
  .kr-about__cards { grid-template-columns: minmax(0, 1fr); }
}

/* Everything lands in its final state rather than simply not animating into
   existence — without this the page is invisible to these users. */
@media (prefers-reduced-motion: reduce) {
  .kr-about__eyebrow,
  .kr-about__title,
  .kr-about__body,
  .kr-about__card,
  .kr-about__frame,
  .kr-approach__step {
    transition: none;
    opacity: 1;
    transform: none;
  }
  .kr-about__frame { clip-path: inset(0 0 0 0); }
  .kr-about__card { transition-duration: .01ms; }
}
`;

/* Without JavaScript the --in class never lands, so the reveal states have to
   be forced or the whole page stays at opacity 0. */
const noscriptCss = `
.kr-about__eyebrow,
.kr-about__title,
.kr-about__body,
.kr-about__card,
.kr-approach__step { opacity: 1; transform: none; }
.kr-about__frame { opacity: 1; clip-path: inset(0 0 0 0); }
`;

const template: AboutTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-about",
  approachClass: "kr-approach",
  timing,
};

export default template;
